nd:var(--el-fill-color-light);padding:12px;border-radius:8px;font-size:12px;line-height:1.6;margin:0}.library-entries{list-style:none;margin:0 0 12px;padding:0;border:1px solid var(--el-border-color-lighter);border-radius:8px}.library-entries li{display:flex;justify-content:space-between;gap:12px;padding:8px 12px;font-size:13px}.library-entries li+li{border-top:1px solid var(--el-border-color-lighter)}.library-entries li span:first-child{min-width:0;overflow-wrap:anywhere}.library-entries li span:last-child{flex:none;color:var(--el-text-color-secondary)}.library-muted{display:block;margin-top:4px;color:var(--el-text-color-secondary);font-size:12px;line-height:1.5}.library-modal p{overflow-wrap:anywhere}.library-modal :deep(.el-select){width:100%}
